import csv,numpy as np,collections
r=list(csv.DictReader(open('responses.csv')));p=np.load('/tmp/p_inc.npy');y=np.array([int(x['rating']) for x in r])
ll=y*np.log(p)+(1-y)*np.log(1-p)
ins=np.array([x['target'] in x['number_set'].split(',') for x in r])
print('inset obs',y[ins].mean(),'pred',p[ins].mean(), ll[ins].sum(), 'all pred',p.mean())
for lo in np.arange(0,1,0.1):
  s=(p>=lo)&(p<lo+0.1)&~ins; print(round(lo,1),s.sum(),y[s].mean() if s.sum() else None, p[s].mean() if s.sum() else None)
g=collections.defaultdict(list)
for i,x in enumerate(r): g[x['number_set']].append(i)
res=sorted(g.items(),key=lambda kv: (ll[kv[1]].sum()))
for k,ix in res[:8]:
  ix=np.array(ix); print(k,len(ix),round(ll[ix].sum(),1),round(y[ix].mean(),2),round(p[ix].mean(),2))
for S in ['23,35,95,83','69,9,39,21','3,33,99']:
  g2=collections.defaultdict(list)
  for i,x in enumerate(r):
    if x['number_set']==S: g2[int(x['target'])].append(i)
  print(S, ' '.join(f'{t}:{y[ix].mean():.1f}/{p[ix[0]]:.2f}' for t,ix in sorted(g2.items())))
"

